import * as THREE from "three";
export const clickPick = (_this) => {
  const rayCaster = new THREE.Raycaster();
  const mouse = new THREE.Vector2();
  let x, y;
  const selectedObjects = [];
  const label = document.querySelector(".label");
  window.addEventListener("click", onMouseClick);
  // 点击卡片的显示位置
  function showCard(element) {
    element.style.display = "block";
    element.style.position = "absolute";
    element.style.left = `170px`;
    element.style.top = "60px";
  }
  function createVideo(path) {
    const parentDiv = document.createElement("div");
    parentDiv.className = "parentVideo";
    parentDiv.style.position = "absolute";
    parentDiv.style.display = "none";
    parentDiv.style.backgroundColor = "rgba(25, 25, 25, 0.5)";
    const titleDiv = document.createElement("div");
    titleDiv.style.cssText =
      "height: 24px;inline-height: 24px;float: left;color: #FFFFFF;font-size:20px;margin:10px 0 10px 20px";
    titleDiv.textContent = "监控录像";
    const closeDiv = document.createElement("div");
    closeDiv.className = "videoImg";
    closeDiv.addEventListener("click", () => {
      const videoDiv = document.querySelectorAll(".parentVideo");
      for (const e of videoDiv) {
        e.remove();
      }
    });
    parentDiv.appendChild(titleDiv);
    parentDiv.appendChild(closeDiv);
    const videoLabel = document.createElement("video");
    videoLabel.autoplay = true;
    videoLabel.muted = true;
    videoLabel.controls = true;
    videoLabel.loop = true;
    videoLabel.style.width = "100%";
    videoLabel.style.height = "350px";
    const videoSource = document.createElement("source");
    videoSource.src = path;
    videoSource.type = "video/mp4";
    videoLabel.appendChild(videoSource);
    parentDiv.appendChild(videoLabel);
    document.body.appendChild(parentDiv);
    showCard(parentDiv, x, y);
  }
  function onMouseClick(e) {
    if (e.changedTouches) {
      x = e.changedTouches[0].pageX;
      y = e.changedTouches[0].pageY;
    } else {
      x = e.clientX;
      y = e.clientY;
    }
    const rect = _this.container.getBoundingClientRect(); // 拿到div相对屏幕坐标的偏移量
    /**
     * 当前场景并不是全屏渲染的 所以屏幕坐标转化为世界坐标的公式有所变化
     */
    mouse.x = ((x - rect.left) / this.container.clientWidth) * 2 - 1;
    mouse.y = -((y - rect.top) / this.container.clientHeight) * 2 + 1;
    // 通过摄像机和鼠标位置来更新射线
    rayCaster.setFromCamera(mouse, _this.camera);
    // 第二个参数表示是否检查他的后代
    const intersects = rayCaster.intersectObjects([_this.scene], true);
    if (intersects.length > 0) {
      console.log(intersects);
      const object_name = intersects[0].object.name;
      // 是否显示卡片
      if (
        intersects.length === 0 ||
        object_name === "" ||
        object_name === "line"
      ) {
        label.style.display = "none";
        _this.click = false;
        return;
      }
      switch (object_name.split("_")[1].substring(0, 3)) {
        // truck
        case "Din":
          _this.dataInfo = [
            { key: "名称", value: object_name },
            { key: "温度", value: Math.round(Math.random() * 20000) },
            { key: "湿度", value: Math.round(Math.random() * 20000) },
          ];
          showCard(label, x, y);
          break;
        case "Pan":
          _this.dataInfo = [
            { key: "名称", value: object_name },
            { key: "温度", value: Math.round(Math.random() * 20000) },
            { key: "湿度", value: Math.round(Math.random() * 20000) },
          ];
          showCard(label, x, y);
          break;
        case "DaL":
          _this.dataInfo = [
            { key: "名称", value: object_name },
            { key: "温度", value: Math.round(Math.random() * 20000) },
            { key: "湿度", value: Math.round(Math.random() * 20000) },
          ];
          showCard(label, x, y);
          break;
        case "Qia":
          _this.dataInfo = [{ key: "名称", value: "正门" }];
          showCard(label, x, y);
          break;
        default:
          label.style.display = "none";
          selectedObjects.pop();
          break;
      }
      if (object_name == "M_jiankong005" && _this.isShowVideo) {
        createVideo("static/video/watch.mp4");
      } else if (object_name == "M_jiankong013" && _this.isShowVideo) {
        createVideo("static/video/watch.mp4");
      } else if (object_name == "M_jiankong007" && _this.isShowVideo) {
        createVideo("static/video/watch.mp4");
      } else if (object_name == "M_jiankong" && _this.isShowVideo) {
        createVideo("static/video/watch.mp4");
      } else if (object_name == "M_jiankong001" && _this.isShowVideo) {
        createVideo("static/video/watch.mp4");
      } else if (object_name == "M_jiankong009" && _this.isShowVideo) {
        createVideo("static/video/watch.mp4");
      } else if (object_name == "M_jiankong011" && _this.isShowVideo) {
        createVideo("static/video/watch.mp4");
      } else if (object_name == "M_jiankong003" && _this.isShowVideo) {
        createVideo("static/video/watch.mp4");
      } else if (object_name == "farmer") {
        console.log('farmer');
      }
      else {
        // label.textContent = soName
        selectedObjects.pop();
        selectedObjects.push(intersects[0].object);
        _this.outlinePass.selectedObjects = selectedObjects;
        _this.effectController.A = object_name;
      }
      _this.click = true;
    } else {
      _this.outlinePass.selectedObjects = [];
    }
  }
};
