<template>
  <el-container
    class="apartmentArea"
    v-loading="loading"
    element-loading-text="拼命加载中...."
    element-loading-spinner="el-icon-loading"
    element-loading-background="rgba(0, 0, 0, 0.8)"
  >
    <el-aside width="180" style="height: 100%">
      <el-menu
        default-active="0"
        background-color="#545c64"
        text-color="#fff"
        active-text-color="#ffd04b"
        @select="handleSelect"
      >
        <div class="user_box">
          <div class="username">
            <i class="el-icon-user-solid"></i>
            {{ username }}
          </div>
          <div></div>
        </div>
        <el-menu-item
          v-for="(item, index) in menuList"
          :key="item.text"
          :index="index.toString()"
        >
          <i :class="item.icon"></i>
          <span>{{ item.text }}</span>
        </el-menu-item>
      </el-menu>
    </el-aside>
    <el-main>
      <div id="container" class="container_box"></div>
      <el-card style="width: 300px" class="label">
        <div v-for="(info, index) in dataInfo" :key="index">
          <span>{{ info.key }}</span>
          <span style="display: inline-block; margin-left: 50px">
            {{ info.value }}
          </span>
          <el-divider />
        </div>
      </el-card>
      <div id="chart1" class="chart chartLayout"></div>
      <div id="chart2" class="chart chartLayout"></div>
      <div
        style="
          position: absolute;
          left: 0px;
          bottom: 0;
          padding: 20px;
          font-weight: bold;
          font-size: 20px;
          color: white;
        "
      >
        <div class="name">姓名：张真</div>
        <div class="school">学校：南阳师范学院</div>
      </div>
    </el-main>
    <!-- NPC -->
    <!-- <NpcDialog ref="npcRef" v-if="isShowNpcDialog"></NpcDialog> -->
    <div class="npc_dialog" ref="closeNpcDialog" v-if="isShowNpcDialog">
      <div class="boxDialog relative rounded-xl">
        <div
          class="close absolute top-4 right-5 text-2xl"
          @click.stop="closeNpcDialog"
        >
          <img
            :src="'static/images/close.png'"
            class="w-12 h-12 relative"
            alt=""
          />
        </div>
        <div
          class="flex items-center flex-col justify-center p-10 dialogContent"
        >
          <!-- 上面 -->
          <div class="top_content flex items-center h-96 w-full p-3">
            <!-- 头像部分 -->
            <div class="avatar_logo w-1/3 h-full">
              <img
                src="static/images/npc.webp"
                class="object-cover w-full h-full"
                alt=""
              />
            </div>
            <div class="next_box relative w-2/3 h-full ml-5 mt-16" style="">
              <div
                id="messages"
                class="msg_box w-full h-96 rounded-md max-h-72"
                style="overflow-y: scroll"
              >
                <div
                  v-for="(msg, index) in messages"
                  :key="index"
                  class="msgItem text-white p-1 overflow-auto"
                >
                  {{ msg.nickname }} : {{ msg.text }}
                </div>
              </div>
            </div>
          </div>
          <!-- 输入框部分 -->
          <!-- <div class="text-white w-10/12 h-10 bg-white mt-5"></div> -->
          <div
            class="mt-1 chatInput_box h-10 flex items-center relative w-10/12 h-10 bg-white mt-5"
          >
            <input
              v-model="generateText"
              @keyup.enter="sendMessage"
              placeholder="输入你想要问的问题"
              class="msgIpt p-1 text-white ml-5 w-10/12 h-full"
            />
            <!-- <button class="bg-white text-center rounded-lg">Send</button> -->
            <div
              class="sendMsg w-20 text-center bg-white rounded-md absolute right-2 cursor-pointer"
              @click.stop="sendMessage"
            >
              确认
            </div>
          </div>
        </div>
      </div>
    </div>
  </el-container>
</template>

<script>
import * as THREE from "three";
import * as echarts from "echarts";
import { initFarm, initFarmer } from "@/utils/modelList";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls";
import { PointerLockControls } from "three/examples/jsm/controls/PointerLockControls";
import { MTLLoader } from "three/examples/jsm/loaders/MTLLoader";
import { OBJLoader } from "three/examples/jsm/loaders/OBJLoader";
import { EXRLoader } from "three/examples/jsm/loaders/EXRLoader";
import { RGBELoader } from "three/examples/jsm/loaders/RGBELoader";
import {
  CSS2DObject,
  CSS2DRenderer,
} from "three/examples/jsm/renderers/CSS2DRenderer";
import { GUI } from "three/examples/jsm/libs/lil-gui.module.min.js";
import Stats from "../../public/static/js/stats";
import { clickPick } from "../../public/static/js/clickPick";
import { EffectComposer } from "three/examples/jsm/postprocessing/EffectComposer";
import { ShaderPass } from "three/examples/jsm/postprocessing/ShaderPass";
import { RenderPass } from "three/examples/jsm/postprocessing/RenderPass";
import { OutlinePass } from "three/examples/jsm/postprocessing/OutlinePass";
import { CopyShader } from "three/examples/jsm/shaders/CopyShader";
import { FXAAShader } from "three/examples/jsm/shaders/FXAAShader";
import { initRenderer, initControls } from "../utils/baseElement";
// import Gsap from "gsap";

import Swal from "sweetalert2";
export default {
  components: {},

  data() {
    return {
      isLoading: false,
      isShowNpcDialog: false,
      menuList: [
        { text: "标签区域", icon: "el-icon-collection-tag" },
        { text: "监控", icon: "el-icon-magic-stick" },
        { text: "高温可视化", icon: "el-icon-eleme" },
        { text: "数据分析", icon: "el-icon-place" },
        { text: "重置视角", icon: "el-icon-loading" },
        { text: "漫游观光", icon: "el-icon-video-camera-solid" },
        { text: "详情页", icon: "el-icon-magic-stick" },
        { text: "AI问答", icon: "el-icon-video-camera-solid" },
      ],
      progress: 0,
      css2dLabelArray: [],
      spriteLabelArray: [],
      effectController: {
        A: "",
      },
      username: "admin",
      dataInfo: [],
      timer: null,
      t: 0,
      loading: true,
      // 火焰信息
      fireArray: [],
      // 正常视角
      normalView: true,
      // 是否展示扫描
      isShowScan: false,
      Controller: {},
      click: false,
      isShowVideo: false,
      isShowCharts: false,
      farmModel: null,
      mixer: null,
      inputText: "张真",
      messages: [
        {
          nickname: "农场管家",
          text: "老板,有什么可以帮到您？",
        },
      ],
      generateText: "",
    };
  },
  mounted() {
    this.animationID = 0;
    this.scene = null;
    this.gui = null;
    this.stats = null;
    this.camera = null;
    this.axes = null;
    this.helper = null;
    this.renderer = null;
    this.fog = null;
    this.controls = null;
    this.lockControls = null;
    this.outlinePass = null;
    this.css2dRender = null;
    this.effectComposer = null;
    this.objList = null;
    this.mixer = null;
    this.texture = null;
    this.mesh2 = null;
    this.ambient = null;
    this.velocity = new THREE.Vector3(); //
    this.direction = new THREE.Vector3(); //第一人称运动的方向
    this.prevTime = performance.now(); //上一次render的时间
    this.moveForward = false; //是否向前运行
    this.moveBackward = false; //是否向后运行
    this.moveLeft = false; //是否向左运行
    this.moveRight = false; //是否向右运行
    this.canJump = false; //是否可以跳
    this.lockcontrols = null;
    this.isShowFire = false;
    this.clock = new THREE.Clock();
    this.container = document.querySelector("#container");
    this.init();
    clearInterval(this.timer);
  },
  beforeDestroy() {
    this.scene.clear();
    this.stats = null;
    this.camera = null;
    this.gui.domElement.style.cssText = "display:none";
    cancelAnimationFrame(this.animationID);
    this.renderer.forceContextLoss();
    this.renderer.dispose();
    this.renderer.content = null;
    const gl = this.renderer.domElement.getContext("webgl");
    gl && gl.getExtension("WEBGL_lose_context").loseContext();
    this.controls = null;
    this.outlinePass = null;
    this.css2dRender = null;
  },
  methods: {
    fakeAnswer() {
      setTimeout(() => {
        this.messages.push({
          nickname: "小云助手",
          text: "这是一个很棒的问题，请充值后获取答案。",
        });
      }, 1500);
    },
    sendMessage() {
      if (this.generateText.trim() !== "") {
        this.messages.push({
          nickname: this.inputText,
          text: this.generateText,
        });
        this.fakeAnswer();
      }
      this.generateText = "";
    },
    focusInput() {
      this.$parent.focusInput();
    },
    blurInput() {
      this.$parent.blurInput();
    },
    closeNpcDialog() {
      this.isShowNpcDialog = false;
      this.isDone = false;
    },
    handleSelect(index) {
      switch (index) {
        case "0":
          this.addCssLabel();
          break;
        case "1":
          this.addCamera();
          break;
        case "2":
          Swal.fire({
            title: "是否开启高温可视化?",
            text: "点击确认开启!",
            icon: "warning",
            showCancelButton: false,
            confirmButtonColor: "#3085d6",
            cancelButtonColor: "#d33",
            confirmButtonText: "确认",
            // cancelButtonText: "关闭",
          }).then((result) => {
            console.log(result);
            if (result.isConfirmed) {
              this.$notify({
                title: "火警",
                message: "养殖区域P-2失火报警",
                type: "warning",
                duration: 4500,
                onClose: () => {
                  console.log("close");
                  this.$notify({
                    title: "自动灭火",
                    message: "灭火已开启，预计5秒后完成",
                    type: "success",
                    duration: 5000,
                    onClose: () => {
                      this.$notify({
                        title: "灭火成功",
                        type: "success",
                      });
                      if (this.fireArray.length > 0) {
                        for (const label of this.fireArray) {
                          label.parent.remove(label);
                        }
                        this.farmModel.children.forEach((child) => {
                          if (child.name == "M_PangZi006") {
                            child.material[1].map =
                              new THREE.TextureLoader().load(
                                "/static/obj/farm/maps/T_Pang_1.jpg"
                              );
                          }
                        });
                        this.fireArray.splice(0);
                        this.isShowFire = false;
                      }
                    },
                  });
                },
              });
              this.changeMode();
            }
          });
          break;
        case "3":
          this.showcharts();
          break;
        case "4":
          this.initViewpoint();
          break;
        case "5":
          this.tourCity();
          break;
        case "6":
          this.$router.push("/DetailPage");
          break;
        case "7":
          this.isShowNpcDialog = !this.isShowNpcDialog;
          break;
      }
    },
    // tourCity
    tourCity() {
      this.normalView = false;
      this.camera.position.y = 100;
      this.camera.lookAt(0, 100, 0);
      this.lockcontrols.getObject().position.x = 0;
      this.lockcontrols.getObject().position.y = 200;
      this.lockcontrols.getObject().position.z = 680;
      this.lockcontrols.lock();
    },
    // 初始化方法
    init() {
      // 初始化场景
      this.initSceneMed();
      // 初始化摄像机
      this.initCamera();
      // 初始化灯光
      this.initLight();
      // 初始化性能检测器
      // this.initStats();
      // 初始化渲染器
      this.initRendererMed();
      // 初始化控制器
      this.initControlsMed();
      // 初始化背景
      this.initRGB();
      // 初始化指针锁定控制器
      this.initPointLockControl();
      this.initComposerMed();
      // this.initClickPick();
      this.AsyncInitModel();
      window.addEventListener("resize", this.onWindowResize, false);
    },
    // 使用async方法加载模型
    async AsyncInitModel() {
      await this.initModelMed("yangzhichang");
      this.initFarmMed();
      // this.initGui();
      this.render();
    },
    initFarmMed() {
      initFarm(this.scene);
      initFarmer(this.scene, this);
    },
    // 初始化场景
    initSceneMed() {
      this.scene = new THREE.Scene();
    },
    // 初始化相机
    initCamera() {
      this.camera = new THREE.PerspectiveCamera(
        45,
        this.container.clientWidth / this.container.clientHeight,
        10,
        100000
      );
      this.camera.position.set(3000, 4500, 7500);
    },
    // 初始化灯光
    initLight() {
      // 点光源(灯泡)
      const PointLight = new THREE.PointLight(0xffffff, 0.6);
      this.scene.add(PointLight);
      // 环境光
      this.ambient = new THREE.AmbientLightProbe(0xffffff, 1.5);
      this.scene.add(this.ambient);
    },
    // 初始化渲染器
    initRendererMed() {
      // css2d渲染器
      this.css2dRender = new CSS2DRenderer();
      // 场景渲染器
      this.renderer = new THREE.WebGLRenderer({
        antialias: true,
        alpha: true,
        logarithmicDepthBuffer: true,
      });
      initRenderer(this.css2dRender, this.container, this.renderer);
    },
    // 初始化控制器
    initControlsMed() {
      // 轨道控制器
      this.controls = new OrbitControls(this.camera, this.renderer.domElement);
      initControls(this.controls);
    },
    // 初始化模型
    initModelMed(url) {
      return new Promise((resolve, reject) => {
        new MTLLoader()
          .setPath("/static/obj/farm/")
          .load(`${url}.mtl`, (materials) => {
            materials.preload();
            new OBJLoader()
              .setMaterials(materials)
              .setPath("/static/obj/farm/")
              .load(`${url}.obj`, (obj) => {
                if (obj) {
                  console.log(obj);
                  this.loading = false;
                  this.farmModel = obj;
                  // obj.scale.set(0.3, 0.3, 0.3);
                  this.scene.add(obj);
                  resolve(obj);
                } else {
                  reject("error");
                }
              });
          });
      });
    },
    // 初始化stats
    initStats() {
      this.stats = new Stats();
      this.stats.domElement.style.position = "absolute";
      this.stats.domElement.style.top = "0px";
      this.stats.domElement.style.left = "180px";
      document.body.appendChild(this.stats.domElement);
      return this.stats;
    },
    // 初始化控制板
    initGui() {
      this.gui = new GUI();
      this.gui.domElement.classList.add();
      this.gui.domElement.style.cssText = "position:absolute;top:0;right:0px;";
      const options = {
        Helper: false,
        Fog: false,
      };
      this.gui.add(this.effectController, "A").name("Selected:").listen();
      this.gui.add(options, "Helper").onChange((val) => {
        if (val) {
          this.axes = new THREE.AxesHelper(5000);
          this.scene.add(this.axes);
          this.helper = new THREE.GridHelper(10000, 2, 0xffffff, 0xffffff);
          this.scene.add(this.helper);
        } else {
          this.scene.remove(this.axes);
          this.scene.remove(this.helper);
        }
      });
      this.gui.add(options, "Fog").onChange((val) => {
        if (val) {
          this.scene.fog = new THREE.Fog("#FFF0F5", 100, 10000);
        } else {
          this.scene.fog = "";
        }
      });
    },
    initRGB() {
      // build
      new EXRLoader().load("/static/images/hdr/bgsky.exr", (texture) => {
        // this.scene.background = texture;
        texture.mapping = THREE.EquirectangularReflectionMapping;
        this.scene.environment = texture;
      });
      new RGBELoader().load("/static/images/hdr/star.hdr", (texture) => {
        this.scene.background = texture;
        texture.mapping = THREE.EquirectangularReflectionMapping;
        // this.scene.environment = texture;
      });
    },
    // 可视化图表
    showcharts() {
      console.log(1111);
      this.isShowCharts = !this.isShowCharts;
      if (this.isShowCharts) {
        this.initCharts();
        document.querySelector("#chart1").style.display = "block";
        document.querySelector("#chart2").style.display = "block";
      } else {
        // this.container.removeChild(document.querySelector("#chart1"));
        document.querySelector("#chart1").style.display = "none";
        document.querySelector("#chart2").style.display = "none";
        // this.container.removeChild(document.querySelector("#chart2"));
      }
    },
    // 初始化图表
    initCharts() {
      for (const ele of document.querySelectorAll(".chart")) {
        ele.style.backgroundColor = "rgba(25,25,25,0.5)";
        ele.style.display = ele.style.display === "block" ? "block" : "block";
      }
      const div1 = document.querySelector("#chart1");
      const div2 = document.querySelector("#chart2");
      const pageChart1 = echarts.init(div1);
      const pageChart2 = echarts.init(div2);
      const option1 = {
        title: {
          text: "部门统计",
          subtext: "人员数据",
          left: "center",
          textStyle: {
            color: "#eee",
          },
        },
        tooltip: {
          trigger: "item",
        },
        legend: {
          orient: "vertical",
          left: "left",
          textStyle: {
            color: "#eee",
          },
        },
        series: [
          {
            name: "Access From",
            type: "pie",
            radius: "50%",
            data: [
              { value: 10, name: "养猪场" },
              { value: 735, name: "dep2" },
              { value: 580, name: "dep3" },
              { value: 484, name: "dep4" },
              { value: 300, name: "dep5" },
            ],
            emphasis: {
              itemStyle: {
                shadowBlur: 10,
                shadowOffsetX: 0,
                shadowColor: "rgba(0, 0, 0, 0.5)",
              },
            },
          },
        ],
      };
      const data = [];
      for (let i = 0; i < 5; ++i) {
        data.push(Math.round(Math.random() * 200));
      }
      const option2 = {
        title: {
          text: "演出欢迎程度",
          subtext: "人员数据",
          left: "center",
          textStyle: {
            color: "#eee",
          },
        },
        xAxis: {
          max: "dataMax",
          textStyle: {
            color: "#eee",
          },
        },
        yAxis: {
          type: "category",
          data: ["A", "B", "C", "D", "E"],
          textStyle: {
            color: "#eee",
          },
          inverse: true,
          animationDuration: 300,
          animationDurationUpdate: 300,
          max: 2, // only the largest 3 bars will be displayed
        },
        series: [
          {
            realtimeSort: true,
            name: "X",
            type: "bar",
            data: data,
            label: {
              show: true,
              position: "right",
              valueAnimation: true,
            },
          },
        ],
        legend: {
          show: true,
          textStyle: {
            color: "#eee",
          },
        },
        animationDuration: 0,
        animationDurationUpdate: 3000,
        animationEasing: "linear",
        animationEasingUpdate: "linear",
      };

      function run() {
        for (let i = 0; i < data.length; ++i) {
          if (Math.random() > 0.9) {
            data[i] += Math.round(Math.random() * 2000);
          } else {
            data[i] += Math.round(Math.random() * 200);
          }
        }
        pageChart2.setOption({
          series: [
            {
              type: "bar",
              data,
            },
          ],
        });
      }

      setTimeout(() => {
        run();
      }, 0);
      setInterval(() => {
        run();
      }, 3000);
      pageChart1.setOption(option1);
      this.container.appendChild(div1);
      pageChart2.setOption(option2);
      this.container.appendChild(div2);
    },
    // 初始化视角
    initViewpoint() {
      this.controls.position0.set(2000, 2000, 2000);
      this.normalView = true;
      this.controls.reset();
    },

    // 初始化效果器
    initComposerMed() {
      this.effectComposer = new EffectComposer(this.renderer);
      this.effectComposer.renderTarget1.stencilBuffer = true;
      this.effectComposer.renderTarget2.stencilBuffer = true;
      // 创建shaderPass 可以在shaderpass里面添加各种着色器达到不同的效果
      const effectCopy = new ShaderPass(CopyShader);
      // 让effectcopy渲染到屏幕上
      effectCopy.renderToScreen = true;
      // 添加renderPass通道,这个通道会渲染场景,但不会将渲染结果输出到屏幕上
      const renderPass = new RenderPass(this.scene, this.camera);
      this.effectComposer.addPass(renderPass);
      this.effectComposer.addPass(effectCopy);
      // outlinePass给对象添加轮廓线
      this.outlinePass = new OutlinePass(
        new THREE.Vector2(window.innerWidth, window.innerHeight),
        this.scene,
        this.camera
      );
      this.outlinePass.edgeStrength = 9; //包围线浓度
      this.outlinePass.visibleEdgeColor.set(0xffd700); //包围线颜色
      this.effectComposer.addPass(this.outlinePass);
      // FXAAShader主要解决锯齿问题
      const effectFXAA = new ShaderPass(FXAAShader);
      effectFXAA.uniforms["resolution"].value.set(
        1 / window.innerWidth,
        1 / window.innerHeight
      );
      effectFXAA.renderToScreen = true;
      this.effectComposer.addPass(effectFXAA);
      clickPick(this);
    },
    // 添加点击效果
    initClickPick() {
      clickPick(this);
    },
    // 初始化指针锁定控制器和监听键盘事件
    initPointLockControl() {
      this.lockcontrols = new PointerLockControls(this.camera, document.body);
      const onKeyDown = (event) => {
        switch (event.keyCode) {
          case 38: // up
          case 87: // w
            this.moveForward = true;
            break;
          case 37: // left
          case 65: // a
            this.moveLeft = true;
            break;
          case 40: // down
          case 83: // s
            this.moveBackward = true;
            break;
          case 39: // right
          case 68: // d
            this.moveRight = true;
            break;
          case 32: // space
            if (this.canJump === true) this.velocity.y += 350;
            this.canJump = false;
            break;
        }
      };
      const onKeyUp = (event) => {
        switch (event.keyCode) {
          case 38: // up
          case 87: // w
            this.moveForward = false;
            break;
          case 37: // left
          case 65: // a
            this.moveLeft = false;
            break;
          case 40: // down
          case 83: // s
            this.moveBackward = false;
            break;
          case 39: // right
          case 68: // d
            this.moveRight = false;
            break;
        }
      };
      document.addEventListener("keydown", onKeyDown, false);
      document.addEventListener("keyup", onKeyUp, false);
    },
    // 第一人称移动 需要在render()里面实时更新位置
    firstPersonMove() {
      // if (this.lockcontrols.isLocked) {
      // 每次都获取上一次的间隔时间 因为根据性能不同每次调用循环函数的时间都是不一样的
      const time = performance.now();
      // 为了不让性能影响操作的速度 我们将他设置为一个因数 所谓性能高那么间隔时间就短
      const delta = (time - this.prevTime) / 1000;
      // 减速因子 设置一下（10）减速因子 他越快整个过程中速度就会越慢 减速的过程就会越快
      this.velocity.x -= this.velocity.x * 10.0 * delta;
      this.velocity.z -= this.velocity.z * 10.0 * delta;
      this.velocity.y -= 9.8 * 100.0 * delta; // 100.0 = mass
      // 方向矢量 鼠标操作的时候控制方向 的变量
      // 如果正数就是往前 负数就是往后
      this.direction.z = Number(this.moveForward) - Number(this.moveBackward);
      this.direction.x = Number(this.moveLeft) - Number(this.moveRight);
      this.direction.normalize(); // 确保了各个方向的一致运动
      // 有一个缓冲作用 避免快速启动 更贴切现实操作 为了保证鼠标抬起后，场景不直接暂停，而是有一个简短的过渡效果
      if (this.moveForward || this.moveBackward)
        this.velocity.z -= this.direction.z * 2000.0 * delta;
      if (this.moveLeft || this.moveRight)
        this.velocity.x -= this.direction.x * 2000.0 * delta;
      // 通过getObject()获取到控制对象 translate改变位置会根据视角调整 更符合现实一点
      this.lockcontrols.getObject().translateX(this.velocity.x * delta * 2);
      this.lockcontrols.getObject().position.y += this.velocity.y * delta; // new behavior
      this.lockcontrols.getObject().translateZ(this.velocity.z * delta * 2);
      // 保证高于地面的距离
      if (this.lockcontrols.getObject().position.y < 200) {
        this.velocity.y = 0;
        this.lockcontrols.getObject().position.y = 200;
        this.canJump = true;
      }
      this.prevTime = time;
      // }
    },
    // 火焰动画
    updateLoop(num) {
      this.t += 0.1; //调节火焰切换速度
      if (this.t > num) this.t = 0;
      //  Math.floor(t)取整 保证一帧一帧切换
      this.texture.offset.x = Math.floor(this.t) / num; // 动态更新纹理偏移 播放关键帧动画 产生火焰然后效果
    },
    render() {
      this.animationID = requestAnimationFrame(this.render);
      // this.renderer.render(this.scene, this.camera);
      if (this.lockcontrols.isLocked) {
        this.firstPersonMove();
      }
      // this.stats.update();
      // 刷新动画
      const delta = this.clock.getDelta();
      // effectComposer里面是对renderer渲染器进行后期处理,则可以在他身上进行render()
      // if (this.click) {
      this.effectComposer.render(delta);
      // }
      this.css2dRender.render(this.scene, this.camera);
      // 扫描效果
      if (this.isShowScan) {
        this.mesh2.rotateZ(0.03);
      }
      if (this.isShowFire) {
        this.updateLoop(15);
      }
      // 轨道控制器和指针锁定控制器会有冲突 不能同时存在
      if (this.normalView) {
        this.controls.update();
      }
      if (this.mixer !== null) {
        // clock.getDelta()方法获得两帧的时间间隔
        this.mixer.update(delta);
      }
    },

    // 切换查看模式
    changeMode() {
      if (this.fireArray.length > 0) {
        for (const label of this.fireArray) {
          label.parent.remove(label);
        }
        this.farmModel.children.forEach((child) => {
          if (child.name == "M_PangZi006") {
            child.material[1].map = new THREE.TextureLoader().load(
              "/static/obj/farm/maps/T_Pang_1.jpg"
            );
          }
        });
        this.fireArray.splice(0);
        this.isShowFire = false;
      } else {
        // const depObj = this.scene.children[this.groupIndex].children.filter(
        //   (item) => item.name.includes("dep")
        // );
        // depObj.forEach((ele) => {
        //   if (ele.name == "dep1") {
        const fire = this.createFlame(8, 0, 300, 0);
        this.isShowFire = true;
        this.fireArray.push(fire);
        this.scene.add(fire);
        // }
        // });
        const scanEffect = this.createScanEffect();
        this.isShowScan = true;
        this.fireArray.push(scanEffect);
        this.scene.add(scanEffect);
        this.farmModel.children.forEach((child) => {
          if (child.name == "M_PangZi006") {
            child.material[1].map = new THREE.TextureLoader().load(
              "/static/obj/farm/maps/T_Pang_red.png"
            );
          }
        });
      }
    },
    // 创建一个HTML标签
    tag(name) {
      // 创建div元素(作为标签)
      let div = document.createElement("div");
      div.innerHTML = name;
      div.classList.add("tag");
      //div元素包装为CSS2模型对象CSS2DObject
      let label = new CSS2DObject(div);
      label.name = "firelabel";
      div.style.pointerEvents = "none"; //避免HTML标签遮挡三维场景的鼠标事件
      // 设置HTML元素标签在three.js世界坐标中位置
      // label.position.set(x, y, z);
      return label; //返回CSS2模型标签
    },
    // 创建一个火焰动画
    createFlame(size, x, y, z) {
      let w = size;
      let h = 1.6 * w;
      const geometry = new THREE.PlaneGeometry(w, h);
      geometry.translate(0, h / 2, 0);
      const textureLoader = new THREE.TextureLoader();
      this.texture = textureLoader.setPath("/static/images/").load("fire.png");
      const num = 15; //火焰多少帧图
      // .repeat方法设置uv两个方向纹理重复数量
      this.texture.repeat.set(1 / num, 1); // 1/num：从图像上截图一帧火焰
      const material = new THREE.MeshBasicMaterial({
        map: this.texture,
        transparent: true,
        opacity: 0.4, //整体调节透明度 和三维场景相融合
        side: THREE.DoubleSide, //双面可见
        depthWrite: false, //是否对深度缓冲区有任何的影响
      });
      const fire = new THREE.Mesh(geometry, material); // 火焰网格模型
      const group = new THREE.Group();
      fire.name = "fire";
      fire.scale.set(50, 50, 50);
      fire.position.set(x / 100, y / 2, z / 100);
      group.add(
        fire,
        fire.clone().rotateY(Math.PI / 2),
        fire.clone().rotateY(Math.PI / 4)
      );
      return group;
    },
    // 创建扫描雷达
    createScanEffect() {
      const geometry = new THREE.PlaneGeometry(100, 100);
      const scan_material = new THREE.MeshBasicMaterial({
        color: "orange",
        map: new THREE.TextureLoader()
          .setPath("/static/images/")
          .load("scan.png"),
        side: THREE.DoubleSide, //两面可见
        transparent: true, //需要开启透明度计算，否则着色器透明度设置无效
        // opacity: 0.5,//整体改变透明度
        depthTest: false,
      });
      this.mesh2 = new THREE.Mesh(geometry, scan_material);
      this.mesh2.position.set(0, 0, 0);
      this.mesh2.rotateX(-Math.PI / 2);
      this.mesh2.scale.set(20, 20, 20);
      return this.mesh2;
    },
    // 添加css2d标签
    addCssLabel() {
      if (this.css2dLabelArray.length > 0) {
        for (const label of this.css2dLabelArray) {
          label.parent.remove(label);
        }
        this.css2dLabelArray.splice(0);
      } else {
        const tag1 = this.tag("养猪区域");
        tag1.position.set(-1400, 300, 0);
        this.scene.add(tag1);
        const tag2 = this.tag("养牛区域");
        tag2.position.set(-200, 300, 100);
        this.scene.add(tag2);
        const tag3 = this.tag("正门");
        tag3.position.set(800, 300, 1200);
        this.scene.add(tag3);
        const tag4 = this.tag("煤气区域");
        tag4.position.set(800, 500, -1000);
        this.scene.add(tag4);
        // labelObj.forEach((ele) => {
        //   const css2dLabel = document.createElement("div");
        //   css2dLabel.innerHTML = `<div style="text-align: center">${ele.name}</div>`;
        //   const label = new CSS2DObject(css2dLabel);
        //   label.name = `${ele.name}csslabel`;
        //   css2dLabel.classList.add("css2dLabel");
        this.css2dLabelArray.push(tag1, tag2, tag3, tag4);
        //   ele.add(label);
        // });
      }
    },
    // 添加摄像头标签
    addCamera() {
      const trr = [
        "M_jiankong013",
        "M_jiankong007",
        "M_jiankong005",
        "M_jiankong",
        "M_jiankong001",
        "M_jiankong009",
        "M_jiankong011",
        "M_jiankong003",
      ];
      if (this.spriteLabelArray.length) {
        trr.forEach((item) => {
          const obj = this.scene.getObjectByName(item);
          obj.material.color.b = 0.588;
          obj.material.color.g = 0.588;
          obj.material.color.r = 0.588;
        });
        this.spriteLabelArray.splice(0);
        this.isShowVideo = false;
      } else {
        trr.forEach((item) => {
          const obj = this.scene.getObjectByName(item);
          console.log(obj);
          obj.material.color.b = 0.288;
          obj.material.color.g = 0.3;
          obj.material.color.r = 3;
          this.spriteLabelArray.push(obj);
        });
        this.isShowVideo = true;
      }
    },

    // 屏幕自适应
    onWindowResize() {
      this.camera.aspect =
        this.container.clientWidth / this.container.clientHeight;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(
        this.container.clientWidth,
        this.container.clientHeight
      );
      this.css2dRender.setSize(
        this.container.clientWidth,
        this.container.clientHeight
      );
    },
  },
};
</script>

